// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 actorSeed, uint256 amRaw) public {
        address actor = vm.addr(uint256(keccak256(abi.encodePacked(actorSeed))) | 1);

        uint256 minSum = c.MinSum(); // 1 ether

        // Put a balance equal to MinSum so the correct contract may collect
        // but the mutant (balance > MinSum) may not.
        vm.deal(actor, minSum);
        vm.prank(actor);
        c.Put{value: minSum}(0);

        (uint256 unlockTime, uint256 balanceBefore) = c.Acc(actor);
        require(balanceBefore == minSum, "unexpected balance");

        // Move past the unlock time so the time guard passes.
        vm.warp(unlockTime + 1);

        // Choose an amount the correct contract should be able to collect.
        uint256 am = bound(amRaw, 0, balanceBefore);
        if (am == 0) {
            return;
        }

        vm.prank(actor);
        try c.Collect(am) {
            ( , uint256 balanceAfter) = c.Acc(actor);
            assertTrue(balanceAfter == balanceBefore - am, "Collect did not deduct the requested amount");
        } catch {
            // A revert is only acceptable if the amount exceeded the balance (it cannot here).
            assertTrue(false, "Collect reverted unexpectedly");
        }
    }
}
